return $input.all().map(item => {
  const row = item.json;
  const ready_to_notify = row.source_system === 'synthetic'
    && /^U[A-Z0-9]{8,}$/.test(String(row.recipient_ref || ''))
    && /^[a-f0-9]{32}$/.test(String(row.notification_key || ''));
  return { json: { ...row, ready_to_notify } };
});

